def forward(self, ...):
    if use_v1_style:
        return self._forward_v1_style(...)  # _forward_v1_style 将被移除

    elif is_encode_only:
        return self._forward_encode(...)    # 保留但重构

    elif use_fia_v2:
        return self._forward_fia_v2(...)    # 将被统一为 fia_v3
    else:
        return self._forward_prefill(...)   # 主路径

fia_mask = self._create_fia_mask(...)
